    if (!s?.shot) return notFound();
    return new Response(Uint8Array.from(atob(s.shot), (c) => c.charCodeAt(0)), { headers: { "Content-Type": "image/jpeg", "Cache-Control": "private, max-age=3600", "X-Robots-Tag": "noindex" } });
