function offersChanges(value) {
  if(!value || typeof value!=='object' || Array.isArray(value))throw new Error('Choose page changes to save.');
  const out={};for(const key of Object.keys(value))if(!['published','headline','intro','items'].includes(key))throw new Error('Unknown page field: '+key+'. Prices are managed in the existing receptionist offer settings.');
  if('published'in value){if(typeof value.published!=='boolean')throw new Error('Choose published or draft.');out.published=value.published;}
  if('headline'in value)out.headline=offersText(value.headline,140,'Headline');
  if('intro'in value)out.intro=offersText(value.intro,600,'Introduction');
  if('items'in value){if(!value.items||typeof value.items!=='object'||Array.isArray(value.items))throw new Error('Choose valid offer cards.');out.items={};for(const[id,changes]of Object.entries(value.items)){
    if(!OFFER_PAGE_ITEMS.some(i=>i.id===id)||!changes||typeof changes!=='object'||Array.isArray(changes))throw new Error('Unknown offer card.');
    const item={};for(const key of Object.keys(changes))if(!['title','description','enabled'].includes(key))throw new Error('Offer cards support title, description and visibility; no unapproved prices or checkout links.');
    if('title'in changes)item.title=offersText(changes.title,100,'Offer title');if('description'in changes)item.description=offersText(changes.description,500,'Offer description');if('enabled'in changes){if(typeof changes.enabled!=='boolean')throw new Error('Choose card visibility.');item.enabled=changes.enabled;}out.items[id]=item;
  }}
  if(!Object.keys(out).length)throw new Error('No page changes supplied.');return out;
}
function offersPrice(value) { return typeof value==='number'&&Number.isFinite(value)&&value>0&&value<=1e6?value:null; }
function offersLink(value) {
  try{const u=new URL(String(value||''));return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}
}
function offersPaymentLink(value) {const link=offersLink(value);if(!link)return '';const u=new URL(link);return ['buy.stripe.com','checkout.stripe.com'].includes(u.hostname)?link:'';}
async function offersState(env) {
  // Do not show fallback prices when storage is unavailable.
  const rows=await select(env,'team_settings','key=in.(offer,offer_catalog)&select=key,value,updated_at');
  const pricingRow=rows.find(r=>r.key==='offer'),catalogRow=rows.find(r=>r.key==='offer_catalog');
  if(pricingRow && (!pricingRow.value || typeof pricingRow.value!=='object' || Array.isArray(pricingRow.value)))throw new Error('Receptionist offer settings could not be verified.');
  if(catalogRow && (!catalogRow.value || typeof catalogRow.value!=='object' || Array.isArray(catalogRow.value)))throw new Error('Offer-page settings could not be verified.');
  const rawPricing=pricingRow?.value || {}, pricing={...DEFAULT_OFFER,...rawPricing};
  const catalog=offersCatalog(catalogRow?.value);
  const revision=await sha(JSON.stringify({pricing:rawPricing,catalog:catalogRow?.value||null,updated_at:catalogRow?.updated_at||null}));
  return {catalog,pricing,revision,catalog_row:catalogRow||null};
}
function offersPublicData(state) {
  return {published:state.catalog.published,headline:state.catalog.headline,intro:state.catalog.intro,items:OFFER_PAGE_ITEMS.map(base=>{
    const i=state.catalog.items[base.id],voice=base.id==='web_voice';
    const pilot=base.id==='chat'?offersPrice(state.pricing.pilot_price):voice?offersPrice(state.pricing.pilot_price_voice):null;
    const monthly=base.id==='chat'?offersPrice(state.pricing.monthly):voice?offersPrice(state.pricing.monthly_voice):null;
    return {id:base.id,group:base.group,title:i.title,description:i.description,features:base.features,enabled:i.enabled,pilot,monthly,pilot_days:Number.isInteger(state.pricing.pilot_days)&&state.pricing.pilot_days>0?state.pricing.pilot_days:null,
      payment_link:pilot&&monthly&&(base.id==='chat'||voice)?offersPaymentLink(voice?state.pricing.payment_link_voice:state.pricing.payment_link):''};
  })};
}
async function offersSave(env,changes,revision) {
  const patch=offersChanges(changes),state=await offersState(env);
  if(typeof revision!=='string'||revision!==state.revision)throw new Error('The offers changed since this page loaded. Refresh and review before saving.');
  const next={...state.catalog,...patch,items:{...state.catalog.items}};
  if(patch.items)for(const[id,item]of Object.entries(patch.items))next.items[id]={...next.items[id],...item};
  if(next.published&&!Object.values(next.items).some(i=>i.enabled))throw new Error('Enable at least one offer before publishing.');
  // Store editable copy only; never duplicate pilot prices or payment links here.
  const value={published:next.published,headline:next.headline,intro:next.intro,items:Object.fromEntries(Object.entries(next.items).map(([id,item])=>[id,{title:item.title,description:item.description,enabled:item.enabled}]))};
  const row={key:'offer_catalog',value,updated_at:now()};
  const saved=state.catalog_row?await update(env,'team_settings','key=eq.offer_catalog&updated_at=eq.'+enc(state.catalog_row.updated_at),{value,updated_at:row.updated_at}):await insertIgnore(env,'team_settings',[row],'key');
  if(!saved.length)throw new Error('Another edit was saved first. Refresh before saving again.');
  await audit(env,{actor:'Ty',action:'offers_page_updated',summary:'Offers page '+(next.published?'published':'saved as draft')+'. Receptionist pricing unchanged.'});
  return {ok:true,public_url:String(env.PUBLIC_ORIGIN||DEFAULT_ORIGIN).replace(/\/+$/,'')+'/offers'};
}
function offersIcon(id) {
  const path=id==='chat'?'<path d="M4 5h16v11H9l-5 4z"/><path d="M8 9h8M8 12h5"/>':id==='web_voice'?'<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M8 21h8"/>':id==='phone'?'<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>':id==='website'?'<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M3 8h18M8 21h8M12 18v3"/>':'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>';
  return '<div class="of-offer-icon" aria-hidden="true"><svg viewBox="0 0 24 24">'+path+'</svg></div>';
}
function offersPageHtml(data,{preview=false}={}) {
  const esc=esc6,book=offersLink(FREE_CALL3),cash=n=>'A$'+Number(n).toLocaleString('en-AU',{maximumFractionDigits:2});
  const action=(href,label,primary=false)=>'<a class="btn '+(primary?'pri':'')+'" href="'+esc(href||'#contact')+'"'+(href?' target="_blank" rel="noopener"':'')+'>'+esc(label)+'</a>';
  const cards=group=>data.items.filter(i=>i.group===group&&i.enabled).map(i=>{
    const fixed=i.pilot&&i.monthly;
    return '<article class="wf-glass of-card" id="'+i.id+'">'+offersIcon(i.id)+'<span class="of-label">'+(i.id==='web_voice'?'VOICE ON YOUR WEBSITE':group==='bundle'?'SCOPED PACKAGE':group==='website'?'DESIGN + BUILD':i.id==='phone'?'PHONE LINE · SEPARATE SETUP':'WEBSITE RECEPTION')+'</span><h3>'+esc(i.title)+'</h3><p class="mu">'+esc(i.description)+'</p><div class="of-price">'+(fixed?'<strong>'+cash(i.pilot)+'</strong><span> '+(i.pilot_days?esc(i.pilot_days)+'-day ':'')+'pilot</span><p>Then '+cash(i.monthly)+' / month</p>':'<strong>Let’s scope it</strong><p>Written quote after a short call</p>')+'</div><ul>'+i.features.map(f=>'<li>'+esc(f)+'</li>').join('')+'</ul>'+(i.id==='web_voice'?'<p class="of-note">Website voice is separate from answering calls to your business phone number.</p>':i.id==='phone'?'<p class="of-note">Phone number, call routing, booking actions and usage are confirmed and tested before launch.</p>':group==='website'?'<p class="of-note">Advanced 3D, integrations, content and ongoing SEO are scoped separately. Search rankings are not guaranteed.</p>':group==='bundle'?'<p class="of-note">Build costs and ongoing services are itemised in your proposal. Any package saving is agreed in writing.</p>':'')+'<div class="acts">'+action(book,group==='bundle'?'Discuss this package':group==='website'?'Discuss your website':i.id==='phone'?'Explore phone reception':'Request a tailored demo',true)+(i.payment_link&&!preview?action(i.payment_link,'Start this pilot'):'')+'</div></article>';
  }).join('');
  const groups=[['receptionist','01 · AI RECEPTION','Make the next enquiry easier to handle.','Start with website chat or voice. We assess telephone reception separately.'],['website','02 · DONE-FOR-YOU WEBSITES','Your website, designed around the next step.','Clear services, considered design and a straightforward path to enquire or book.'],['bundle','03 · CONNECTED PACKAGES','Bring the website and receptionist together.','One project plan, with the build, setup and continuing services clearly scoped.']].filter(([g])=>data.items.some(i=>i.group===g&&i.enabled));
  return '<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AI Receptionists & Website Builds | Studio Flow & Systems</title><meta name="description" content="Explore Studio Flow AI website receptionists, done-for-you website builds and connected packages. Book a call to find the right scope for your business."><style>'+APP.css+OFFERS_PAGE_CSS+'</style></head><body><input class="of-motion-switch" type="checkbox" id="of-motion-paused" aria-label="Pause ambient motion"><div class="of-shell"><header class="of-nav"><a href="/offers" aria-label="Studio Flow offers"><img src="/app/logo.webp?v='+APP.v+'" alt="Studio Flow & Systems" width="240" height="38"></a><nav aria-label="Offers navigation">'+groups.map(([g,,h])=>'<a href="#'+g+'">'+(g==='receptionist'?'AI receptionists':g==='website'?'Websites':'Packages')+'</a>').join('')+action(book,'Book a call')+'<label for="of-motion-paused" class="btn ghost of-motion-control"><span class="of-motion-on">Pause motion</span><span class="of-motion-off">Resume motion</span></label></nav></header>'+(preview?'<p class="of-preview">PRIVATE LAYOUT PREVIEW · Changes are not published by opening this preview.</p>':'')+'<main><section class="of-hero"><div><span class="wf-eyebrow">STUDIO FLOW &amp; SYSTEMS · AUSTRALIA</span><h1>'+esc(data.headline)+'</h1><p>'+esc(data.intro)+'</p><div class="acts">'+action(book,'Find the right fit',true)+'<a class="btn ghost" href="#'+(groups[0]?.[0]||'contact')+'">Explore the offers ↓</a></div><p class="of-note">A short conversation. A clear scope. A practical next step.</p></div><div class="of-visual"><span class="of-orbit" aria-hidden="true"></span><span class="of-orbit two" aria-hidden="true"></span><svg class="of-signal" viewBox="0 0 600 600" aria-hidden="true"><path class="of-wire" d="M40 420 C120 420 110 180 260 180 S480 150 560 60 M30 240 C130 240 180 480 350 480 S470 310 590 310"/><path class="of-wire-flow" d="M40 420 C120 420 110 180 260 180 S480 150 560 60 M30 240 C130 240 180 480 350 480 S470 310 590 310"/><circle cx="40" cy="420" r="3"/><circle cx="560" cy="60" r="3"/><circle cx="590" cy="310" r="3"/></svg><div class="of-scene-orb" aria-hidden="true"><svg viewBox="0 0 200 200"><ellipse cx="100" cy="100" rx="30" ry="94"/><ellipse cx="100" cy="100" rx="65" ry="94"/><ellipse cx="100" cy="100" rx="94" ry="30"/><ellipse cx="100" cy="100" rx="94" ry="65"/><path d="M6 100H194 M100 6V194"/></svg></div><div class="of-concept wf-glass" aria-label="Illustrative website and receptionist concept"><div class="of-browser"><i></i><i></i><i></i><span>YOUR BUSINESS, CONNECTED</span></div><span class="of-label">ILLUSTRATIVE WEBSITE CONCEPT</span><h2>A warm welcome.<br>A clear next step.</h2><p class="mu">Your services, your brand,<br>and an easier way to enquire.</p><div class="of-mini-actions"><span>Explore services</span><span>Make an enquiry ↗</span></div><div class="of-chat"><div class="of-orb" aria-hidden="true"></div><div><b>Your AI receptionist</b><p>Answers from your approved business information.</p></div></div><div class="of-journey"><span>Enquiry</span><i>→</i><span>Answer</span><i>→</i><span>Next step</span></div></div><span class="of-mini-tag" aria-hidden="true">Website + reception, connected</span></div></section>'+groups.map(([g,label,h,sub])=>'<section class="of-section" id="'+g+'"><div class="of-section-heading"><span class="wf-eyebrow">'+label+'</span><h2>'+h+'</h2><p class="mu">'+sub+'</p></div><div class="of-cards of-'+g+'">'+cards(g)+'</div></section>').join('')+'<section class="wf-glass of-process"><div><span class="wf-eyebrow">HOW WE GET THERE</span><h2>Built around your business.</h2></div><ol><li><b>Understand</b><p>We look at your services, enquiries and existing tools.</p></li><li><b>Shape &amp; review</b><p>Agree the scope, preview the experience and confirm the content.</p></li><li><b>Test &amp; launch</b><p>Check the connections and handoffs, then launch with your sign-off.</p></li></ol></section><section class="of-faq"><h2>A few things to know.</h2><details><summary>Does website voice answer my phone line?</summary><p>No. Website voice lets people speak through the website. Telephone reception is a separate service requiring an eligible number, routing and testing.</p></details><details><summary>What do SEO foundations include?</summary><p>We scope the essentials such as page structure, service content and metadata. Ongoing local SEO, Google Business Profile work and ranking improvements require their own scope. Rankings are not guaranteed.</p></details><details><summary>Can the website include motion or 3D?</summary><p>We can discuss the visual direction during scoping. Complex 3D, custom animation and integrations are quoted to match the work and performance requirements.</p></details><details><summary>What is included in a bundle?</summary><p>The selected website and receptionist services, itemised in your proposal. Setup, build costs, usage limits and ongoing monthly services are confirmed before work starts.</p></details></section><section class="wf-glass of-close" id="contact"><span class="wf-eyebrow">LET’S MAKE THE NEXT STEP SIMPLE</span><h2>Start with the part your business needs most.</h2><p class="mu">Tell us what happens when someone visits, enquires or calls. We will help you choose the right starting point.</p>'+action(book,'Book a short call',true)+'</section></main><footer class="of-footer"><img src="/app/logo.webp?v='+APP.v+'" width="190" height="30" alt="Studio Flow & Systems"><p>Prices shown in AUD. GST treatment, usage limits, scope and terms are confirmed in your proposal. Pilot fees and recurring services are separate. No package saving is assumed.</p><p>© '+new Date().getUTCFullYear()+' Studio Flow &amp; Systems</p></footer></div></body></html>';
}
async function offersPublic(request,env) {
  if(!['GET','HEAD'].includes(request.method))return new Response('Use GET or HEAD.',{status:405,headers:{Allow:'GET, HEAD'}});
  try{
    const state=await offersState(env),data=offersPublicData(state);
    if(!data.published)return new Response(request.method==='HEAD'?null:'This offers page is not published yet.',{status:404,headers:{'Content-Type':'text/plain; charset=utf-8','Cache-Control':'no-store','X-Robots-Tag':'noindex'}});
    return new Response(request.method==='HEAD'?null:offersPageHtml(data),{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",'Permissions-Policy':'camera=(), microphone=(), geolocation=()'}});
  }catch{return new Response('The offers page is temporarily unavailable. Please try again shortly.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8','Cache-Control':'no-store','Retry-After':'60'}});}
}
