var API3 = "https://api.anthropic.com/v1/messages";
var MAX_STEPS = 16;
var MAX_TOKENS = 8e3;
var MAX_TOOL_RESULT = 14e3;
async function callClaude(env, body) {
  for (let attempt = 0; attempt < 4; attempt++) {
    const res = await fetch(API3, {
      method: "POST",
      headers: {
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json"
      },
      body: JSON.stringify(body)
    });
    if (res.ok) return res.json();
    const text = await res.text();
    if (res.status === 400 && body.tool_choice && /tool_choice/i.test(text)) {
      const { tool_choice, ...rest } = body;
      body = rest;
      continue;
    }
    if ((res.status === 429 || res.status >= 500) && attempt < 2) {
      await new Promise((r) => setTimeout(r, 1500 * (attempt + 1)));
      continue;
    }
    throw new Error(`Claude ${res.status}: ${text.slice(0, 400)}`);
  }
}
async function memoryBlock(env) {
  try {
    const rows = await select(env, "team_memory", "order=created_at.desc&limit=60&select=category,fact");
    return rows.length ? rows.map((r) => `- [${r.category}] ${r.fact}`).join("\n") : "(nothing saved yet)";
  } catch {
    return "(memory unavailable)";
  }
}
